package com.finanscore.report.messaging;import com.fasterxml.jackson.databind.ObjectMapper;import com.finanscore.contracts.*;import com.finanscore.report.application.*;import com.finanscore.report.infrastructure.*;import com.finanscore.support.idempotency.*;import com.finanscore.support.observability.ObservabilityContext;import com.finanscore.support.outbox.*;import io.opentelemetry.instrumentation.annotations.WithSpan;import org.slf4j.Logger;import org.slf4j.LoggerFactory;import org.springframework.kafka.annotation.KafkaListener;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;import java.time.*;import java.util.*;import java.nio.charset.StandardCharsets;
@Component public class ReportConsumer{private static final Logger log=LoggerFactory.getLogger(ReportConsumer.class);private final ObjectMapper om;private final ReportRepository repo;private final PdfReportGenerator pdf;private final MinioReportStorage storage;private final IdempotentEventGuard guard;private final OutboxService outbox;public ReportConsumer(ObjectMapper o,ReportRepository r,PdfReportGenerator p,MinioReportStorage s,IdempotentEventGuard g,OutboxService b){om=o;repo=r;pdf=p;storage=s;guard=g;outbox=b;}
 @WithSpan("generate-report") @KafkaListener(topics=EventTopics.SCORING_CALCULATED,groupId="report-generation") @Transactional public void on(String raw)throws Exception{var e=om.readValue(raw,EventEnvelope.class);try(var ignored=ObservabilityContext.bind(e)){if(guard.alreadyProcessed(e.eventId(),"report-generation"))return;UUID req=UUID.fromString(String.valueOf(e.payload().get("requestId")));if(repo.findByRequestId(req).isPresent()){guard.markProcessed(e.eventId(),"report-generation");return;}byte[] bytes=pdf.generate(e.payload());UUID id=UUID.nameUUIDFromBytes(("report:"+req).getBytes(StandardCharsets.UTF_8));String key="reports/"+req+"/final.pdf";storage.put(key,bytes);var r=new ReportEntity();r.id=id;r.requestId=req;r.userId=Long.valueOf(String.valueOf(e.payload().get("userId")));r.objectKey=key;r.status="AVAILABLE";r.createdAt=Instant.now();repo.save(r);Map<String,Object> p=new LinkedHashMap<>();p.put("requestId",req.toString());p.put("userId",r.userId);p.put("reportId",id.toString());p.put("objectKey",key);outbox.append("ReportGenerated",req.toString(),e.correlationId(),e.eventId(),null,"report-service",p);log.info("Report generated reportId={} objectKey={}",id,key);guard.markProcessed(e.eventId(),"report-generation");}}}
